    'UI_BACKUP_TRANSPORT_SELECT_TIPS' => '网络传输:备份数据将通过LAN网络传输到备份存储<br><br>SAN传输(LAN-Free):备份数据通过SAN传输到备份存储,需要先配置LAN-Free存储<br><br>网络加密传输 : 备份数据通过SSL加密传输<br><br>热添加传输(LAN-Free) : 备份数据通过SAN网络把磁盘附加到备份服务器上,需要先配置LAN-Free存储<br><br>如果SAN传输未生效,会自动使用网络传输',
    'UI_BACKUP_TRANSPORT_VMWARE_SELECT_TIPS' => '网络传输:备份数据将通过LAN网络传输到备份存储<br><br>SAN传输(LAN-Free):备份数据通过SAN传输到备份存储,需要先配置LAN-Free存储<br><br>网络加密传输 : 备份数据通过SSL加密传输<br><br>热添加传输 : 通过ESXI的SCSI HotAdd特性将目标磁盘挂载到备份服务器/代理上，实现数据的直接访问<br><br>如果SAN传输未生效,会自动使用网络传输',
